3: //! Small, allocation-free command parsing for Rustix's Crabshell.
4: //!
5: //! This crate deliberately contains no terminal, filesystem, or kernel code.
6: //! The same command model can later be driven by a graphical terminal frontend
7: //! or a userspace process without coupling it to the current serial console.
8: 
9: /// The longest command line accepted by the bootstrap shell, excluding its NUL.
10: pub const MAX_LINE_LENGTH: usize = 256;
11: 
12: /// Parsed shell operations. The command borrows its path and text from the input
13: /// line, so parsing needs no allocator and the caller controls all I/O.
14: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
15: pub enum Command<'a> {
16:     Help,
17:     Clear,
18:     Pwd,
19:     Meminfo,
20:     Ls(Option<&'a str>),
21:     Cd(&'a str),
22:     Mkdir(&'a str),
23:     Touch(&'a str),
24:     Write {
25:         path: &'a str,
26:         contents: &'a str,
27:     },
28:     Append {
29:         path: &'a str,
30:         contents: &'a str,
31:     },
32:     Cp {
33:         source: &'a str,
34:         destination: &'a str,
35:     },
36:     Mv {
37:         source: &'a str,
38:         destination: &'a str,
39:     },
40:     Cat(&'a str),
41:     Rm(&'a str),
42:     Rmdir(&'a str),
43: }
44: 
45: /// Errors in command syntax. Unknown command names are reported separately so
46: /// the caller can echo the original name in its diagnostic.
47: #[derive(Clone, Copy, Debug, PartialEq, Eq)]
48: pub enum ParseError {
49:     UnknownCommand,
50:     MissingArgument,
51:     MissingText,
52:     TooManyArguments,
53:     UnterminatedQuote,
54: }
55: 
56: /// Parse one command line. An empty or whitespace-only line returns `Ok(None)`.
57: ///
58: /// `write` and `append` accept the remaining text verbatim; wrapping the whole
59: /// text in matching single or double quotes removes those outer quotes. Escape
60: /// sequences and quoted paths are intentionally not part of this first grammar.
61: pub fn parse(line: &str) -> Result<Option<Command<'_>>, ParseError> {
62:     let line = line.trim();
63:     if line.is_empty() {
64:         return Ok(None);
65:     }
66: 
67:     let (name, rest) = take_word(line).ok_or(ParseError::MissingArgument)?;
68:     let command = match name {
69:         "help" => {
70:             no_arguments(rest)?;
71:             Command::Help
72:         }
73:         "clear" => {
74:             no_arguments(rest)?;
75:             Command::Clear
76:         }
77:         "pwd" => {
78:             no_arguments(rest)?;
79:             Command::Pwd
80:         }
81:         "meminfo" => {
82:             no_arguments(rest)?;
83:             Command::Meminfo
84:         }
85:         "ls" => Command::Ls(optional_path(rest)?),
86:         "cd" => Command::Cd(one_path(rest)?),
87:         "mkdir" => Command::Mkdir(one_path(rest)?),
88:         "touch" => Command::Touch(one_path(rest)?),
89:         "write" => {
90:             let (path, contents) = path_and_text(rest)?;
91:             Command::Write { path, contents }
92:         }
93:         "append" => {
94:             let (path, contents) = path_and_text(rest)?;
95:             Command::Append { path, contents }
96:         }
97:         "cp" => {
98:             let (source, destination) = two_paths(rest)?;
99:             Command::Cp {
100:                 source,
101:                 destination,
102:             }
103:         }
104:         "mv" => {
105:             let (source, destination) = two_paths(rest)?;
106:             Command::Mv {
107:                 source,
108:                 destination,
109:             }
110:         }
111:         "cat" => Command::Cat(one_path(rest)?),
112:         "rm" => Command::Rm(one_path(rest)?),
113:         "rmdir" => Command::Rmdir(one_path(rest)?),
114:         _ => return Err(ParseError::UnknownCommand),
115:     };
116: 
117:     Ok(Some(command))
118: }
119: 
120: fn take_word(input: &str) -> Option<(&str, &str)> {
121:     let input = input.trim_start();
122:     if input.is_empty() {
123:         return None;
124:     }
125:     let end = input.find(char::is_whitespace).unwrap_or(input.len());
126:     Some((&input[..end], input[end..].trim_start()))
127: }
128: 
129: fn no_arguments(rest: &str) -> Result<(), ParseError> {
130:     if rest.is_empty() {
131:         Ok(())
132:     } else {
133:         Err(ParseError::TooManyArguments)
134:     }
135: }
136: 
137: fn optional_path(rest: &str) -> Result<Option<&str>, ParseError> {
138:     match take_word(rest) {
139:         None => Ok(None),
140:         Some((path, rest)) => {
141:             no_arguments(rest)?;
142:             Ok(Some(path))
143:         }
144:     }
145: }
146: 
147: fn one_path(rest: &str) -> Result<&str, ParseError> {
148:     let (path, rest) = take_word(rest).ok_or(ParseError::MissingArgument)?;
149:     no_arguments(rest)?;
150:     Ok(path)
151: }
152: 
153: fn two_paths(rest: &str) -> Result<(&str, &str), ParseError> {
154:     let (source, rest) = take_word(rest).ok_or(ParseError::MissingArgument)?;
155:     let (destination, rest) = take_word(rest).ok_or(ParseError::MissingArgument)?;
156:     no_arguments(rest)?;
157:     Ok((source, destination))
158: }
159: 
160: fn path_and_text(rest: &str) -> Result<(&str, &str), ParseError> {
161:     let (path, text) = take_word(rest).ok_or(ParseError::MissingArgument)?;
162:     if text.is_empty() {
163:         return Err(ParseError::MissingText);
164:     }
165: 
166:     let first = text.as_bytes()[0];
167:     if first == b'\'' || first == b'"' {
168:         if text.len() < 2 || text.as_bytes()[text.len() - 1] != first {
169:             return Err(ParseError::UnterminatedQuote);
170:         }
171:         return Ok((path, &text[1..text.len() - 1]));
172:     }
173: 
174:     Ok((path, text))
175: }
