189:     fn parses_basic_navigation_and_file_commands() {
190:         assert_eq!(parse("pwd"), Ok(Some(Command::Pwd)));
191:         assert_eq!(parse("meminfo"), Ok(Some(Command::Meminfo)));
192:         assert_eq!(parse("ls /home"), Ok(Some(Command::Ls(Some("/home")))));
193:         assert_eq!(parse("cd .."), Ok(Some(Command::Cd(".."))));
194:         assert_eq!(
195:             parse("mkdir /tmp/work"),
196:             Ok(Some(Command::Mkdir("/tmp/work")))
197:         );
198:         assert_eq!(
199:             parse("touch note.txt"),
200:             Ok(Some(Command::Touch("note.txt")))
201:         );
202:         assert_eq!(parse("cat note.txt"), Ok(Some(Command::Cat("note.txt"))));
203:         assert_eq!(
204:             parse("cp note.txt copy.txt"),
205:             Ok(Some(Command::Cp {
206:                 source: "note.txt",
207:                 destination: "copy.txt",
208:             }))
209:         );
210:         assert_eq!(
211:             parse("mv copy.txt saved.txt"),
212:             Ok(Some(Command::Mv {
213:                 source: "copy.txt",
