219:     #[test]
220:     fn write_preserves_spaces_and_strips_outer_quotes() {
221:         assert_eq!(
222:             parse("write greeting.txt hello from crabshell"),
223:             Ok(Some(Command::Write {
224:                 path: "greeting.txt",
225:                 contents: "hello from crabshell",
226:             }))
227:         );
228:         assert_eq!(
229:             parse("append greeting.txt \" again\""),
230:             Ok(Some(Command::Append {
231:                 path: "greeting.txt",
232:                 contents: " again",
233:             }))
234:         );
235:         assert_eq!(
236:             parse("write empty.txt \"\""),
237:             Ok(Some(Command::Write {
238:                 path: "empty.txt",
239:                 contents: "",
240:             }))
241:         );
242:     }
243: 
244:     #[test]
245:     fn validates_command_arity_and_text() {
246:         assert_eq!(parse("cd"), Err(ParseError::MissingArgument));
247:         assert_eq!(parse("pwd now"), Err(ParseError::TooManyArguments));
248:         assert_eq!(parse("cp only-one"), Err(ParseError::MissingArgument));
249:         assert_eq!(parse("mv a b c"), Err(ParseError::TooManyArguments));
250:         assert_eq!(parse("write file"), Err(ParseError::MissingText));
251:         assert_eq!(
252:             parse("write file \"unfinished"),
253:             Err(ParseError::UnterminatedQuote)
254:         );
255:         assert_eq!(parse("not-a-command"), Err(ParseError::UnknownCommand));
256:     }
257: }

