370:         if self.node(directory).ok()?.kind != EntryKind::Directory {
371:             return None;
372:         }
373:         self.nodes
374:             .iter()
375:             .filter(|node| {
376:                 node.used
377:                     && node.parent == directory
378:                     && !(directory == ROOT_NODE && node.name_len == 0)
379:             })
380:             .nth(ordinal)
381:             .map(|node| Entry {
382:                 name: node.name(),
383:                 kind: node.kind,
384:                 size: node.data_len,
385:             })
